-- Every returned value is an error count. No identifiers/source rows are emitted.
SELECT
 (SELECT COUNT(*)-COUNT(DISTINCT event_id) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity`) AS duplicate_learning_facts,
 (SELECT COUNT(*)-COUNT(DISTINCT event_id) FROM `${project_id}.bdc_core_${environment}.fact_recommendation_event`) AS duplicate_recommendation_facts,
 (SELECT COUNT(*)-COUNT(DISTINCT event_id) FROM `${project_id}.bdc_core_${environment}.fact_llm_attempt`) AS duplicate_llm_attempts,
 (SELECT COUNT(*) FROM `${project_id}.bdc_governance_${environment}.platform_identity_conflicts`) AS conflicting_platform_identities,
 (SELECT COUNT(*) FROM `${project_id}.bdc_governance_${environment}.learning_identity_conflicts`) AS conflicting_learning_identities,
 (SELECT COUNT(*)-COUNT(DISTINCT user_sk) FROM `${project_id}.bdc_core_${environment}.dim_user`) AS duplicate_user_keys,
 (SELECT COUNT(*)-COUNT(DISTINCT course_sk) FROM `${project_id}.bdc_core_${environment}.dim_course`) AS duplicate_course_keys,
 (SELECT COUNT(*)-COUNT(DISTINCT feature_sk) FROM `${project_id}.bdc_core_${environment}.dim_feature`) AS duplicate_feature_keys,
 (SELECT COUNT(*)-COUNT(DISTINCT date_sk) FROM `${project_id}.bdc_core_${environment}.dim_date`) AS duplicate_date_keys,
 (SELECT COUNT(*)-COUNT(DISTINCT time_sk) FROM `${project_id}.bdc_core_${environment}.dim_time`) AS duplicate_time_keys,
 (SELECT COUNT(*)-COUNT(DISTINCT model_sk) FROM `${project_id}.bdc_core_${environment}.dim_ai_model`) AS duplicate_model_keys,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_user` d USING(user_sk) WHERE d.user_sk IS NULL) AS orphan_learning_user,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_course` d USING(course_sk) WHERE d.course_sk IS NULL) AS orphan_learning_course,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_feature` d USING(feature_sk) WHERE d.feature_sk IS NULL) AS orphan_learning_feature,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_date` d USING(date_sk) WHERE d.date_sk IS NULL) AS orphan_learning_date,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_time` d USING(time_sk) WHERE d.time_sk IS NULL) AS orphan_learning_time,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_recommendation_event` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_user` d USING(user_sk) WHERE d.user_sk IS NULL) AS orphan_recommendation_user,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_recommendation_event` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_course` d USING(course_sk) WHERE f.course_sk IS NOT NULL AND d.course_sk IS NULL) AS orphan_recommendation_course,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_recommendation_event` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_date` d USING(date_sk) WHERE d.date_sk IS NULL) AS orphan_recommendation_date,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_llm_attempt` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_ai_model` d USING(model_sk) WHERE f.model_sk IS NOT NULL AND d.model_sk IS NULL) AS orphan_llm_model,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_llm_attempt` f LEFT JOIN `${project_id}.bdc_core_${environment}.dim_date` d USING(date_sk) WHERE d.date_sk IS NULL) AS orphan_llm_date,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity` WHERE occurred_at>TIMESTAMP_ADD(CURRENT_TIMESTAMP(),INTERVAL 5 MINUTE)) AS future_learning_events,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_recommendation_event` WHERE occurred_at>TIMESTAMP_ADD(CURRENT_TIMESTAMP(),INTERVAL 5 MINUTE)) AS future_recommendation_events,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_llm_attempt` WHERE occurred_at>TIMESTAMP_ADD(CURRENT_TIMESTAMP(),INTERVAL 5 MINUTE)) AS future_llm_attempts,
 (SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_llm_attempt` WHERE usage_status='unknown' AND (prompt_tokens IS NOT NULL OR completion_tokens IS NOT NULL)) AS invalid_unknown_usage,
 ABS((SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_learning_activity`)-(SELECT COUNT(*) FROM `${project_id}.bdc_core_${environment}.fact_content_interaction`)) AS compatibility_fact_difference;
